BackgroundJob.Enqueue(() => Console.WriteLine("Hello from Hangfire!"));

// Delayed job
BackgroundJob.Schedule(() => Console.WriteLine("Delayed!"), TimeSpan.FromMinutes(5));

// Recurring job
RecurringJob.AddOrUpdate(() => Console.WriteLine("Recurring!"), Cron.Daily);
